      detailedDefinitionEn = "A terminal scribal annotation found on cuneiform tablets and monumental stelae specifying the copyist's signature, patronymic, exact date by regnal year, line census, and apotropaic curse formulas against vandalism.",
      inscriptionalWitnessesAr = "خواتيم ألواح مكتبة آشوربانيبال في نينوى، ورُقم ملحمة كرت وملحمة بعل بأوغاريت (توقيع الكاتب إليميلكو الإيليراني 𐎛𐎍𐎎𐎍𐎋)، وتابوت أشمون عازر بصيدا.",
      inscriptionalWitnessesEn = "Library of Ashurbanipal cuneiform colophons, Ugaritic Baal cycle tablets signed by chief scribe Ilimilku (𐎛𐎍𐎎𐎍𐎋), and the Eshmunazar sarcophagus of Sidon.",
      ancientSampleGlyphs = "𐎉𐎔𐎊 . 𐎛𐎍𐎎𐎍𐎋 . 𐎌𐎁𐎐𐎊 (كتبه إليميلكو الشوباني)",
      ancientScriptType = "المسماري الأوغاريتي والأكادي (Ugaritic & Akkadian)",
      philologicalImportanceAr = "يمنح الباحثين الإسناد التاريخي الموثق والكرونولوجيا المطلقة للنصوص، ويوثق تقاليد المدارس الإبيغرافية والمجمع العلمي الملكي.",
      philologicalImportanceEn = "Provides absolute chronological synchronisms, documents scribal lineages and editorial practices across the ancient Levant and Mesopotamia.",
      relatedTermIds = listOf("damnatio_memoriae", "logogram", "cuneiform"),
      citation = "Hunger, H. (Babylonische und assyrische Kolophone); Pardee, D."
    ),

    EpigraphicGlossaryTerm(
      id = "squeeze_estampage",
      termAr = "البصمة الورقية / الشَّمْعية للنقش (إستامباج)",
      termEn = "Epigraphic Squeeze / Estampage",
      transliteration = "estampage / squeeze",
      categoryAr = "الآثار ومواد التدوين",
      categoryEn = "Archaeology & Paleography",
      shortDefinitionAr = "نسخة مقلوبة ثلاثية الأبعاد للنقش الحجري تؤخذ بضغط ورق ترشيح مبلل أو مطاط سائل على الصخرة لاستخراج تفاصيل الحفر.",
      shortDefinitionEn = "A exact 3D mechanical impression of an engraved stone inscription made with damp filter paper or latex.",
      detailedDefinitionAr = "تقنية توثيق إبيغرافية كلاسيكية ذات أهمية قصوى. يُضغط ورق ترشيح خاص مبلل بالماء بعناية بواسطة فرشاة شعر خشنة داخل أخاديد الحروف المنحوتة في الصخر. بعد جفافه، يُنزع ليعطي قالباً دقيقاً يعكس عمق الحفر الحجري، مما يسمح بقراءة الحروف المتآكلة التي يتعذر تمييزها بالعين المجردة تحت الإضاءة المائلة.",
      detailedDefinitionEn = "A foundational field technique in epigraphy. Dampened heavy rag paper or liquid latex is beaten into the incised stone surface. Once dried, it yields a high-fidelity negative relief that captures weathered letter strokes under raking light.",
      inscriptionalWitnessesAr = "بصمة المستشرق الفرنسي شارل كليرمون جانو لمسلة ميشع في ذيبان عام 1869 (قبل أن يُحطمها البدو بالنار)، وبصمات هالوجيف لـ نقوش مأرب وصرواح باليمن.",
      inscriptionalWitnessesEn = "Clermont-Ganneau's historic 1869 paper squeeze of the Mesha Stele before its fragmentation; Eduard Glaser and Joseph Halévy squeezes of South Arabian Sabaean inscriptions.",
      ancientSampleGlyphs = "قوالب سلبية للحروف الغائرة تبرز بالألوان المائلة",
      ancientScriptType = "التوثيق الميداني للنقوش (Epigraphic Field Methods)",
      philologicalImportanceAr = "أنقذت هذه الطريقة عشرات النقوش الخالدة من الضياع بعد تعرض حجارتها للتكسير أو العوامل الجوية، وهي الشاهد الأوثق في المتاحف العالمية.",
      philologicalImportanceEn = "Preserved priceless historical records whose physical originals were subsequently damaged or lost, remaining primary sources for decipherment.",
      relatedTermIds = listOf("ductus", "palimpsest", "ostrakon"),
      citation = "Woodhead, A. G. (The Study of Greek Inscriptions); Lemaire, A."
    ),

    EpigraphicGlossaryTerm(
      id = "damnatio_memoriae",
      termAr = "طَمْس الذِّكْرى الأثري (دمناتيو ميمورياي)",
      termEn = "Damnatio Memoriae",
      transliteration = "damnatio memoriae (لعنة الذكرى)",
      categoryAr = "الآثار ومواد التدوين",
      categoryEn = "Archaeology & Paleography",
      shortDefinitionAr = "الإزميل المتعمد لمحو أو كشط اسم ملك أو حاكم أو إله من فوق المسلات والحجارة لإلغاء وجوده التاريخي.",
      shortDefinitionEn = "The intentional physical erasure or chiseling out of a ruler or deity's name from public monuments to expunge their memory.",
      detailedDefinitionAr = "ممارسة سياسية ودينية شائعة في الشرق الأدنى القديم، حيث يقوم الملك المنتصر أو الحاكم الجديد بنقر وكشط أسماء خصومه وتماثيلهم من فوق الألواح والمسلات التذكارية، ليُحكم عليهم بالنسيان الأبدي، مما يخلق ثغرات (Lacunae) في المتن الإبيغرافي يحتاج المستكشف إلى ترميمها سياقياً.",
      detailedDefinitionEn = "A ritualized political erasure where successor monarchs obliterated the names, titles, and depictions of deposed rulers from stelae and palace reliefs, creating critical lacunae that modern philologists must reconstruct.",
      inscriptionalWitnessesAr = "نقش تل القاضي (دان) الآرامي (محو اسم الملك الإسرائيلي)، كشط أسماء ملوك سبأ وحمير في بعض نقوش المعارك، وطمس أسماء العمارنة في مصر القديمة.",
      inscriptionalWitnessesEn = "Tel Dan Stele fragments, Sabaic monumental inscriptions showing erased cartouches after dynastic coups, and Assyrian palace bas-reliefs.",
      ancientSampleGlyphs = "[𐤌𐤋𐤊 . ...] فجوات محفورة عمداً فوق الأسماء",
      ancientScriptType = "تحليل المتن وتاريخ الحفريات (Contextual Epigraphy)",
      philologicalImportanceAr = "يُعد شاهداً فيزيائياً على الانقلابات السياسية والصراعات العسكرية، ويُفسر للباحث سبب خلو بعض الأسطر المتصلة من أسماء أبطالها.",
      philologicalImportanceEn = "Provides concrete material evidence of political upheavals, regime changes, and damnative sanctions across the ancient Levant.",
      relatedTermIds = listOf("colophon", "palimpsest", "stele"),
      citation = "Flower, H. I. (The Art of Forgetting); Hallo, W. W. (The Context of Scripture)."
    ),

    EpigraphicGlossaryTerm(
      id = "zabur",
      termAr = "خَطُّ الزَّبُور اليَمَاني (الكتابة الشَّعبية السريعة)",
      termEn = "Zabur (South Arabian Cursive)",
      transliteration = "Zabūr (المسند الشعبي الحبري)",
      categoryAr = "الإبيغرافيا والخطوط",
      categoryEn = "Epigraphy & Scripts",
      shortDefinitionAr = "الخط العربي الجنوبي اللين والسريع المكتوب بالحبر أو المحفور بسكين على عسب النخل وعيدان الخشب للمعاملات اليومية.",
      shortDefinitionEn = "The ancient South Arabian cursive script inscribed with stylus or ink on wooden sticks and palm-leaf stalks for daily administrative contracts.",
      detailedDefinitionAr = "الوجه الحيوي اليومي لحضارات اليمن القديم (سبأ، معين، قتبان، حضرموت). بينما كان خط المسند البارز مخصصاً للمسلات الملكية والنذور الدينية في المعابد، كان خط الزبور هو خط الشعب والمعاملات: كعقود البيع والديون، والرسائل الشخصية، والوصفات الطبية، يدونه الكاتب بحركات رشيقة ملتوية على أعواد الخشب اللينة.",
      detailedDefinitionEn = "The everyday cursive counterpart to monumental Musnad in Ancient South Arabia. Thousands of inscribed wooden sticks excavated in Yemen reveal private correspondence, commercial promissory notes, legal codes, and inventories.",
      inscriptionalWitnessesAr = "آلاف العيدان الخشبية المحفوظة في المتحف الوطني بصنعاء والمتحف البريطاني (مجموعات ريكمانس، ومولر، ومحمد بافقيه).",
      inscriptionalWitnessesEn = "The massive corpus of inscribed palm-leaf ribs and wooden sticks in the National Museum of Sana'a and British Museum, deciphered by Ryckmans, Müller, and Stein.",
      ancientSampleGlyphs = "خطوط مسندية لينة مائلة ومتشابكة الحروف",
      ancientScriptType = "الزبور العربي الجنوبي القديم (Zabur Cursive)",
      philologicalImportanceAr = "أحدث ثورة في فهم الحياة الاقتصادية والاجتماعية واللغوية في جزيرة العرب، وأثبت وجود مجتمع مدني متقدم واسع القراءة والكتابة في الألف الأول ق.م.",
      philologicalImportanceEn = "Revolutionized understanding of South Arabian socio-economic life and vernacular grammar, demonstrating widespread literacy far beyond monumental propaganda.",
      relatedTermIds = listOf("boustrophedon", "ductus", "ostrakon"),
      citation = "Stein, P. (Die altsüdarabischen Holzstäbchen, 2010); Ryckmans, J."
    ),

    // 2. Semitic Phonology & Sound Shifts
    EpigraphicGlossaryTerm(
      id = "canaanite_shift",
      termAr = "التَّحَوُّل الكَنْعَاني (*ā > ō)",
      termEn = "The Canaanite Shift",
      transliteration = "Canaanite Vowel Shift (*ā > ō)",
      categoryAr = "علم الأصوات السامية",
      categoryEn = "Semitic Phonology",
      shortDefinitionAr = "قانون صوتي تاريخي انقلبت فيه ألف المد الطويلة المنبورة في السامية الأم (*ā) إلى واو مفخمة أو مضمومة (ō) في الفرع الكنعاني.",
      shortDefinitionEn = "A foundational historical sound shift wherein Proto-Semitic stressed long *ā shifted to a rounded back vowel /ō/ across Canaanite dialects.",
      detailedDefinitionAr = "الظاهرة الصوتية الحاكمة التي تُميز اللغات الكنعانية (الفينيقية، البونية، العبرية، المؤابية، العمونية) عن سائر اللغات السامية الأخرى (كالأكادية والآرامية والعربية والسبئية). فكلمة 'سلام' السامية الأم (*śalām-) تحولت في الكنعانية إلى (šalōm)، و'عالم' (*ʿālam-) إلى (ʿōlām)، و'أنا' (*ʾanāku) إلى (ʾanōkī).",
      detailedDefinitionEn = "The primary diagnostic phonological isogloss defining the Canaanite branch of Northwest Semitic. Proto-Semitic *ā under stress shifted unconditionally to /ō/ (e.g. *śalām- -> šalōm 'peace', *ṭāb- -> ṭōb 'good', *ʿālam- -> ʿōlām 'eternity').",
      inscriptionalWitnessesAr = "نقوش جبيل وقرطاج الفينيقية والبونية، مسلة ميشع المؤابية، رسائل تل العمارنة (حيث سُجلت الكلمات الكنعانية بأحرف مسمارية أكادية، مثل: anuki / rūšu = رأس).",
      inscriptionalWitnessesEn = "Amarna Canaanite glosses (e.g. anuki for *ʾanāku, zuruḥ for *ḏirāʿ), Byblian and Punic stelae, Mesha Stele, and Biblical Hebrew Tiberian pointing.",
      ancientSampleGlyphs = "*śalām- ➔ 𐤔𐤋𐤌 (šalōm) | *ʾanāku ➔ 𐤀𐤍𐤊 (ʾanōkī)",
      ancientScriptType = "الفينيقي والكنعاني والمؤابي (Canaanite Northwest Semitic)",
      philologicalImportanceAr = "يُعد المعيار الصوتي الذهبي لتصنيف أي نقش لغوي مجهول في بلاد الشام وفلسطين؛ فإذا وُجد التحول كان النقش كنعانياً، وإذا غاب كان آرامياً أو عربياً أو شرقياً.",
      philologicalImportanceEn = "Serves as the ultimate linguistic litmus test for categorizing Northwest Semitic epigraphs as Canaanite versus Aramaic or peripheral dialects.",
      relatedTermIds = listOf("begadkefat", "diphthong_contraction", "isogloss"),
      citation = "Garr, W. R. (Dialect Geography of Syria-Palestine); Friedrich & Röllig (Phönizisch-Punische Grammatik)."
    ),

    EpigraphicGlossaryTerm(
      id = "begadkefat",
      termAr = "قاعدة بَجَد كَفَت (التسهيل الاحتكاكي للصوامت الانفجارية)",
      termEn = "Begadkefat Lenition",
      transliteration = "bgdkpt / bəgadkəp̄at",
      categoryAr = "علم الأصوات السامية",
      categoryEn = "Semitic Phonology",
      shortDefinitionAr = "تسهيل الصوامت الانفجارية الستة (ب، ج، د، ك، ف، ت) إلى أصوات احتكاكية رخوة (v, ɣ, ð, x, f, θ) عندما تسبقها حركة مصوتة.",
      shortDefinitionEn = "The post-vocalic spirantization of the six Semitic non-emphatic plosives (b, g, d, k, p, t) into their corresponding fricatives.",
      detailedDefinitionAr = "قانون صوتي وتأثير فونولوجي في السامية الشمالية الغربية (خاصة الآرامية والعبرية). عندما يأتي أي من هذه الحروف الستة بعد صائت (حركة قصيرة أو طويلة) ودون أن يكون مشدداً، يتحول نطقه من صوت شديد انفجاري إلى صوت رخو احتكاكي؛ فتنطق /b/ كـ [v] أو [β]، وتنطق /k/ كـ [x] كحرف الخاء، وتنطق /t/ كـ [θ] كالثاء.",
      detailedDefinitionEn = "A phonological allophonic rule where plosives /b, g, d, k, p, t/ soften to fricatives [v, ɣ, ð, x, f, θ] following a vowel, fundamental to Classical Syriac, Biblical Aramaic, and Tiberian Hebrew phonology.",
      inscriptionalWitnessesAr = "نقوش البرديات الآرامية بالإمبراطورية الأخمينية (إلفنتين)، والنقوش السريانية الإسطرنجيلية بالرها وتدمر، والمخطوطات الماسورية العبرية.",
      inscriptionalWitnessesEn = "Elephantine Aramaic papyri, Palmyrene bilinguals, Classical Syriac manuscripts with Rukkakha/Qushaya dots, and Tiberian Masoretic codices.",
      ancientSampleGlyphs = "𐡁, 𐡂, 𐡃, 𐡊, 𐡐, 𐡕 (بَجَد كَفَت)",
      ancientScriptType = "الآرامي والسرياني والعبري (Aramaic & Northwest Semitic)",
      philologicalImportanceAr = "يُفسر تباين الترجمات الصوتية اليونانية واللاتينية للأسماء السامية القديمة في العهدين القديم والجديد (مثل تحول بارثولوميو وكفرناحوم).",
      philologicalImportanceEn = "Explains discrepancies in Greek and Latin transliterations of Semitic toponyms and personal names, and illuminates late Northwest Semitic consonant dynamics.",
      relatedTermIds = listOf("canaanite_shift", "pharyngealization_emphatics"),
      citation = "Kutscher, E. Y. (A History of the Aramaic Language); Joüon & Muraoka."
    ),

    EpigraphicGlossaryTerm(
      id = "pharyngealization_emphatics",
      termAr = "الإطباق والاستعلاء السامي (الأصوات المفخمة)",
      termEn = "Pharyngealization / Semitic Emphatics",
      transliteration = "Emphatic Consonants (الأصوات المطبقة)",
      categoryAr = "علم الأصوات السامية",
      categoryEn = "Semitic Phonology",
      shortDefinitionAr = "خاصية نطقية سامية فريدة تتم بتضييق تجويف البلعوم أو قذف الهواء الحنجري لتفخيم الصوامت (ط، ص، ض، ظ، ق).",
      shortDefinitionEn = "A distinctive Semitic phonological series articulated either with secondary pharyngeal constriction or glottalic ejection.",
      detailedDefinitionAr = "إحدى أخص خصائص عائلة اللغات السامية مقارنة باللغات الهندو-أوروبية. تتألف هذه السلسلة من الصوامت المطبقة (*ṭ, *ṣ, *ṣ́, *ẓ, *q). تباين تحقيقها عبر التاريخ؛ فبينما تحققت في العربية والآرامية المتأخرة بالإطباق البلعومي (Pharyngealization)، أعيد تركيبها في السامية الأم والسامية الإثيوبية والأكادية القديمة كأصوات قذفية حنجرية (Ejectives / Glottalized: [tʼ, sʼ, kʼ]).",
      detailedDefinitionEn = "A defining triad of Proto-Semitic phonology contrasting with voiced and voiceless stops. While Central Semitic (Arabic) developed pharyngealized 'velarized' realization, Afroasiatic and Ethiosemitic preserve archaic ejective articulations.",
      inscriptionalWitnessesAr = "شواهد خط المسند السبئي (تمييز دقيق بين الظاء 𐩼، والضاد 𐩳، والطاء f، والصاد 𐩮)، ونقوش أوغاريت المسمارية، وشواهد الجعزية الحبشية بأكسوم.",
      inscriptionalWitnessesEn = "Ancient South Arabian Musnad (contrasting 𐩼 ẓ, 𐩳 ḍ, 𐩷 ṭ, 𐩮 ṣ), Ugaritic 30-letter cuneiform, and Ge'ez royal epigraphs of Aksum.",
      ancientSampleGlyphs = "𐩷 (ṭ) , 𐩮 (ṣ) , 𐩳 (ḍ) , 𐩼 (ẓ) , 𐩤 (q)",
      ancientScriptType = "السامية الأم والمسند والجعزي (Proto-Semitic Core)",
      philologicalImportanceAr = "يُعد الحفاظ على كامل سلسلة الصوامت المطبقة (دون اندماج) علامة على أصالة اللغة ومحافظتها على النظام الفونولوجي للسامية الأم.",
      philologicalImportanceEn = "Essential for reconstructive comparative linguistics; scripts that collapsed emphatics (like Phoenician 22 letters) show structural loss compared to Musnad and Arabic.",
      relatedTermIds = listOf("ejectives", "lateral_fricatives"),
      citation = "Cantineau, J. (Études de linguistique sémitique); Lipiński, E. (Semitic Languages: Outline of a Comparative Grammar)."
    ),

    EpigraphicGlossaryTerm(
      id = "lateral_fricatives",
      termAr = "الصوامت الجانبية السامية (الشين والضاد القديمة)",
      termEn = "Lateral Fricatives",
      transliteration = "Lateral Consonants (*ś, *ṣ́)",
      categoryAr = "علم الأصوات السامية",
      categoryEn = "Semitic Phonology",
      shortDefinitionAr = "أصوات احتكاكية يُفرغ هواؤها من جانبي اللسان وليس من وسطه، وهي النطق الأصلي لصوت الشين السامية الثالثة والضاد القديمة.",
      shortDefinitionEn = "Fricative consonants produced by releasing airflow along the sides of the tongue, reconstructed for Proto-Semitic *ś and emphatic *ṣ́.",
      detailedDefinitionAr = "أثبتت الفيلولوجيا السامية الحديثة أن السامية الأم كانت تحوي ثلاثة أصوات صفيرية سنية-لثوية للشين والسين، منها الصوت الجانبي الصامت (*ś = /ɬ/) الشبيه بنطق الـ Ll الويلزية. هذا الصوت لا يزال حياً حتى اليوم في اللغات العربية الجنوبية الحديثة (المهرية، السقطرية، الشحرية الجبالية)، وكان هو النطق الأصلي لحرف الشين الثاني في العبرية والمسند السبئي.",
      detailedDefinitionEn = "Phonemes characterized by lateral airstream release (/ɬ/ and /ɬʼ/). Retained living today exclusively in Modern South Arabian languages (Mehri, Soqotri, Jibbali/Shehri) and preserved in early Hebrew (Śin vs Šin).",
      inscriptionalWitnessesAr = "نقوش المسند السبئي التي تفرق بين السين الأولى (𐩯 s¹)، والسين الثانية الجانبية (𐩪 s² = ś)، والسين الثالثة (𐩰 s³)، ونقوش البادية الثمودية والصفائية.",
      inscriptionalWitnessesEn = "Ancient South Arabian sibilant triad (s¹, s², s³), Epigraphic Safaitic cairns, and early Aramaic loanwords in Assyrian texts.",
      ancientSampleGlyphs = "𐩪 (s² / ś جانبي) | 𐩳 (ṣ́ / ضاد جانبية)",
      ancientScriptType = "المسند واللغات الجنوبية الحديثة (Musnad & MSAL)",
      philologicalImportanceAr = "حل أعظم لغز في تطور الأبجديات السامية وفسر سبب وجود أصوات متعددة للشين والسين في المعاجم المقارنة.",
      philologicalImportanceEn = "Solved the historic mystery of the Semitic sibilants and explained the tri-sibilant system of Old South Arabian and Modern South Arabian.",
      relatedTermIds = listOf("pharyngealization_emphatics", "canaanite_shift"),
      citation = "Beeston, A. F. L. (Sabaic Grammar); Johnstone, T. M. (Jibbāli Lexicon); Rubin, A. D."
    ),

    // 3. Morphology & Epigraphic Syntax
    EpigraphicGlossaryTerm(
      id = "status_constructus",
      termAr = "الحالة البنائية / الإضافة السامية (ستاتوس كونستروكتوس)",
      termEn = "Status Constructus",
      transliteration = "Status Constructus (الإضافة السامية)",
      categoryAr = "الصرف والمورفولوجيا",
      categoryEn = "Morphology & Grammar",
      shortDefinitionAr = "تجريد الاسم المضاف من التنوين أو الميمية أو أدوات التعريف لتثبيته في علاقة ملكية مع الاسم المضاف إليه.",
      shortDefinitionEn = "The morphologically reduced bound state of a noun heading a genitive possessive construction, shedding nunation or determiners.",
      detailedDefinitionAr = "بنية تركيبية ومورفولوجية سامية أصيلة تقع عندما يضاف اسم إلى اسم آخر للدلالة على التملك أو الوصف. في هذه الحالة يخضع الاسم المضاف لاختصار وزني وصوتي؛ فيفقد علامة التنوين أو الميمية (Nunation/Mimation)، وتسقط نون التثنية والجمع، وتتحول تاء التأنيث المربوطة من هاء وقفية إلى تاء صريحة منطوقة (مثل: مَلْكَة ➔ مَلْكَت قَرْطاج).",
      detailedDefinitionEn = "The syntactic bond where the head noun directly governs a following genitive noun. The construct form undergoes phonetic shortening, loss of case nunation/mimation, and reduction of vowel quantity (e.g. malku -> malik bīti).",
      inscriptionalWitnessesAr = "كافة النصوص الإبيغرافية السامية: مسلة حمورابي (bānī bītim = باني البيت)، مسلة أحيرام (mlk gbl = ملك جبيل)، ونقش محرم بلقيس بسبأ (بني أوم).",
      inscriptionalWitnessesEn = "Universal across all Semitic epigraphy: Akkadian royal stelae (šar mātātim 'king of lands'), Phoenician sarcophagi, and Sabaean temple dedications.",
      ancientSampleGlyphs = "𐤌𐤋𐤊 . 𐤂𐤁𐤋 (ملك جبيل) | 𐩨𐩬𐩺 . 𐩱𐩥𐩣 (بناة أوام)",
      ancientScriptType = "السامية المشتركة (Pan-Semitic Core)",
      philologicalImportanceAr = "يُعد المفتاح النحوي لفك تراكيب الجمل الملكية والنذرية وألقاب الملوك وكشف علاقات التملك والأنساب في النقوش.",
      philologicalImportanceEn = "Essential for establishing syntactic hierarchy, parsing compound titles, identifying patronymics, and tracing case-ending reductions.",
      relatedTermIds = listOf("mimation_nunation", "waw_consecutive"),
      citation = "Brockelmann, C. (Grundriss der vergleichenden Grammatik der semitischen Sprachen); Moscati et al."
    ),

    EpigraphicGlossaryTerm(
      id = "mimation_nunation",
      termAr = "الميمية والتنوين التحديدي (ميميشن / نونيشن)",
      termEn = "Mimation & Nunation",
      transliteration = "Mimation (-m) & Nunation (-n)",
      categoryAr = "الصرف والمورفولوجيا",
      categoryEn = "Morphology & Grammar",
      shortDefinitionAr = "إلحاق حرف الميم (-m) أو النون (-n) في أواخر الأسماء المعربة للدلالة على تمام الاسم أو تنكيره أو تعريفه الصرفي.",
      shortDefinitionEn = "The morphological affixation of final /-m/ (mimation) or /-n/ (nunation) marking nominal case completion, definiteness, or indeterminacy.",
      detailedDefinitionAr = "خاصية إعرابية مورفولوجية سامية قديمة. في السامية الشرقية (الأكادية القديمة والبابلية) والسامية الجنوبية القديمة (المسند السبئي والقتباني)، تظهر اللاحقة الميمية (-m: مثل šarrum في الأكادية، ومَلِكُم في السبئية). بينما في السامية الغربية والوسطى (العربية والآرامية) حلت اللاحقة النونية (-n: كالتنوين العربي، والتعريف بالنون السرياني والآرامي).",
      detailedDefinitionEn = "A foundational morphological nominal marker. East Semitic (Akkadian) and Ancient South Arabian (Musnad) employ mimation (-um, -im, -am), whereas Central Semitic (Arabic, Aramaic) shifted to nunation (-un, -in, -an).",
      inscriptionalWitnessesAr = "شريعة حمورابي (awīlum = الإنسان)، نقوش مأرب السبئية (شرحبيلم، بيتم = بيت/البيت)، ونقش النمارة بالعربية النبطية.",
      inscriptionalWitnessesEn = "Code of Hammurabi (wardum 'slave', awīlum 'citizen'), Sabaic monumental stelae (byt-m 'house'), and the Namara Nabataeo-Arabic inscription.",
      ancientSampleGlyphs = "𐩨𐩺𐩩𐩣 (byt-m = بيتاً / البيت) | 𒈗 𒄠 (šarr-um = مَلِك)",
      ancientScriptType = "الأكادي والمسند والعربي القديم (Akkadian, Sabaic, Arabic)",
      philologicalImportanceAr = "يُعد شاهداً بارزاً على تطور نظام الحركات والإعراب التام، ويوضح انقسام العائلة السامية إلى فرع ميمي وفرع نوني.",
      philologicalImportanceEn = "Marks chronological stages of noun declension; its dissolution in Late Bronze/Iron Age marks the transition toward uninflected dialects.",
      relatedTermIds = listOf("status_constructus", "isogloss"),
      citation = "Gelb, I. J. (Sequential Reconstruction of Proto-Akkadian); Kogan, L. (Genealogical Classification of Semitic)."
    ),

    EpigraphicGlossaryTerm(
      id = "waw_consecutive",
      termAr = "واو العطف السردية التتابعية (واو الانقلاب / وايقطول)",
      termEn = "Waw Consecutive / Inversive",
      transliteration = "Waw Consecutive (Wayyiqṭol)",
      categoryAr = "الصرف والمورفولوجيا",
      categoryEn = "Morphology & Grammar",
      shortDefinitionAr = "دخول واو العطف على الفعل المضارع مع تضعيف سابقه لقلب دلالته الزمنية إلى الماضي السردي المتتابع.",
      shortDefinitionEn = "A distinctive syntactic construction where a prefixed conjunction *wa-* transforms an imperfective verb form into a narrative past.",
      detailedDefinitionAr = "تركيب نحوي بارز يربط الأفعال في السرد القصصي والتاريخي. عند دخول الواو المشبعة على صيغة الفعل المبتدئ بالسابقة (*yaqtul)، لا تفيد الاستقبال بل تقلب معنى الفعل ليكون ماضياً مسروداً متتابع الأحداث (مثل: فَقَاتَلْتُ، وَأَخَذْتُ، وَبَنَيْتُ). يُمثل استمراراً لصيغة الماضي القديمة ذات السوابق في السامية الشرقية (Akkadian iprus).",
      detailedDefinitionEn = "A hallmark narrative tense of ancient Northwest Semitic epigraphy. A prefixed conjunction *wa-* with gemination alters the prefix conjugation (*yaqtul) into a preterite past aspect, driving chronological storytelling.",
      inscriptionalWitnessesAr = "مسلة ميشع المؤابية (استخدام متكرر لا ينقطع: 'وَأَعْسَفْ' = وقاتلت، 'وَأُوحِزْ' = وأخذت، 'وَأَسْكُنْ' = وسكنت)، نقش دير علا الجلعادي، والعبرية القديمة التوراتية.",
      inscriptionalWitnessesEn = "The Mesha Stele of Moab (e.g. wʾltḥm 'and I fought', wʾḥz 'and I captured'), Deir Alla plaster inscription (prophecy of Balaam), and archaic Biblical poetry.",
      ancientSampleGlyphs = "𐤅𐤀𐤋𐤕𐤇𐤌 . 𐤁𐤒𐤓 (وقتلتُ بالقرية) | 𐤅𐤀𐤏𐤔 (وصنعتُ)",
      ancientScriptType = "المؤابي والكنعاني القديم (Moabite & Early Hebrew)",
      philologicalImportanceAr = "يُثبت الوحدة النحوية العميقة بين لهجات بلاد الشام في العصر الحديدي، ويُعيد وصل صيغة الفعل السامي بصيغة الماضي الرافدية الأكادية (Iprus).",
      philologicalImportanceEn = "Provides grammatical proof of close genetic affinity across Iron Age Transjordan and the Levant, preserving archaic preterite morphology.",
      relatedTermIds = listOf("status_constructus", "canaanite_shift"),
      citation = "Smith, M. S. (The Origins of Biblical Hebrew); Niccacci, A. (The Syntax of the Verb in Classical Hebrew Prose)."
    ),

    EpigraphicGlossaryTerm(
      id = "t_infix_stems",
      termAr = "الأوزان المفتعلة بالتاء المُنغرسة (T-Infix Stems)",
      termEn = "T-Infixed Verbal Stems",
      transliteration = "Gt / Ifteʿal Stems (الوزن المفتعل)",
      categoryAr = "الصرف والمورفولوجيا",
      categoryEn = "Morphology & Grammar",
      shortDefinitionAr = "انغراس حرف التاء داخل جذر الفعل بعد الفاء الأصلية (افتعل) لإفادة المطاوعة أو المشاركة أو انعكاس الحدث.",
      shortDefinitionEn = "Verbal derivations characterized by the insertion of an infixed /-t-/ morpheme directly after the first root radical.",
      detailedDefinitionAr = "ظاهرة صرفية أصيلة في عائلة اللغات السامية. بدلاً من إضافة التاء كسلسلة سابقة، يتم غرسها داخل البنية الصامتة للجذر بعد الصامت الأول؛ مثل وزن (Gt) في الأكادية (iktazba)، ووزن (افتعل / yiftaʿala) في العربية والسبئية والمؤابية (مثل: 'لتحم' = اقتتل وحارب).",
      detailedDefinitionEn = "A widespread Proto-Semitic morphosyntactic pattern where an infixed reflexive/reciprocal marker /-t-/ is inserted internal to the triliteral root (e.g. Akkadian Gt *imtaḫaṣ, Moabite *wʾltḥm 'and I engaged in warfare', Arabic iftaʿala).",
      inscriptionalWitnessesAr = "مسلة ميشع المؤابية (الفعل 'ولتحم' 𐤅𐤀𐤋𐤕𐤇𐤌)، نصوص حمورابي الملكية، نقوش المعارك السبئية في صرواح، والنصوص الفينيقية الملكية.",
      inscriptionalWitnessesEn = "Mesha Inscription line 11 (wʾltḥm bqr 'and I fought against the town'), Akkadian legal codes, and Sabaean military chronicles (e.g. hqny w-ftḫ).",
      ancientSampleGlyphs = "𐤅𐤀𐤋𐤕𐤇𐤌 (و-أ-ل-ت-ح-م من جذر لحم) | 𐩱𐩡𐩩𐩢𐩣",
      ancientScriptType = "الأكادي والمسند والمؤابي (Akkadian, Sabaic, Moabite)",
      philologicalImportanceAr = "يُعد دليلاً صرفياً حاسماً على عمق الروابط البنيوية المشتركة بين اللغات السامية من بلاد الرافدين إلى اليمن وبلاد الشام.",
      philologicalImportanceEn = "Key diagnostic showing deep genetic morpho-syntax across all geographic poles of Semitic, from ancient Mesopotamia to South Arabia and the Levant.",
      relatedTermIds = listOf("status_constructus", "waw_consecutive"),
      citation = "Huehnergard, J. (Comparative Semitic Linguistics); Lipiński, E."
    ),

    // 4. Archaeology & Paleography
    EpigraphicGlossaryTerm(
      id = "ostrakon",
      termAr = "الشَّقْفَة الفَخَّارية المنقوشة (أوستراكون)",
      termEn = "Ostrakon / Ostraca",
      transliteration = "óstrakon (ὄστρακον)",
      categoryAr = "الآثار ومواد التدوين",
      categoryEn = "Archaeology & Paleography",
      shortDefinitionAr = "كسرة من إناء فخاري مكسور يُعاد استخدامها كسطح للكتابة بالحبر أو الحفر للرسائل والمذكرات السريعة.",
      shortDefinitionEn = "A broken pottery shard utilized as a ubiquitous, inexpensive writing surface for letters, tax tallies, and receipts.",
      detailedDefinitionAr = "المادة التدوينية الشعبية الأكثر انتشاراً في العالم القديم. نظراً لغلاء الرقوق والبردي، كان الناس والجنود والإداريون يلتقطون شقف الجرار الفخارية المكسورة لكتابة الأوامر العسكرية، وإيصالات توريد الزيت والنبيذ، والمراسلات الميدانية العاجلة بواسطة الحبر الأسود وقلم القصب.",
      detailedDefinitionEn = "Discarded ceramic sherds repurposed across the ancient Near East as disposable notebooks. Because pottery was virtually indestructible, ostraca preserve invaluable vernacular correspondence, military despatches, and commercial receipts.",
      inscriptionalWitnessesAr = "رسائل لخيش الفخارية الشهيرة (عشية الغزو البابلي لأورشليم عام 586 ق.م)، شقفات السامرة الإدارية، وشقفات إلفنتين الآرامية بمصر.",
      inscriptionalWitnessesEn = "Lachish Ostraca (describing military beacon signals during Nebuchadnezzar's invasion), Samaria administrative ostraca, and Elephantine Aramaic dockets.",
      ancientSampleGlyphs = "شقف فخارية منقوشة بالمداد الكربوني الأسود",
      ancientScriptType = "الخط الكنعاني والآرامي السريع (Cursive Ostraca)",
      philologicalImportanceAr = "تنقل اللغة الحية الواقعية اليومية للجنود والفلاحين والموظفين بعيداً عن الصياغات الدعائية الملكية المعقمة المنحوتة على المسلات.",
      philologicalImportanceEn = "Provides rare unvarnished glimpses into colloquial grammar, military intelligence, and paleographical cursive evolution away from monumental royal propaganda.",
      relatedTermIds = listOf("palimpsest", "squeeze_estampage", "ductus"),
      citation = "Torczyner, H. (Lachish I: The Lachish Letters); Renz & Röllig (Handbuch der althebräischen Epigraphik)."
    ),

    EpigraphicGlossaryTerm(
      id = "stele",
      termAr = "المَسَلَّة النَّصْبِيَّة التذكارية (ستيلا)",
      termEn = "Stele / Monolith",
      transliteration = "stḗlē (στήλη) / النصب التذكاري",
      categoryAr = "الآثار ومواد التدوين",
      categoryEn = "Archaeology & Paleography",
      shortDefinitionAr = "لوح حجري مستطيل أو مقوس الرأس يُنصب في الساحات أو المعابد لتدوين الشرائع أو الانتصارات العسكرية أو المآثر الملكية.",
      shortDefinitionEn = "An upright stone monument or slab bearing commemorative inscriptions, legal codes, religious decrees, or royal triumphs.",
      detailedDefinitionAr = "النصب الأثري والعمود الحجري القائم المنحوت من حجر البازلت الأسود أو الحجر الجيري الصلب. توضع المسلات في مداخل المعابد وحواضر المدن لتوثيق إنجازات الملك وانتصاراته، ونسب الفضل للآلهة، وإعلان الشرائع والقوانين لعامة الشعب لتبقى خالدة عبر القرون.",
      detailedDefinitionEn = "A free-standing dressed stone monument erected publicly to broadcast royal prestige, legal codes, boundary demarcations, or divine covenants, often carved with relief imagery atop historical narratives.",
      inscriptionalWitnessesAr = "مسلة شريعة حمورابي (حجر الديوريت الأسود باللوفر)، مسلة ميشع ملك مؤاب (البازلت الأسود)، مسلة تل القاضي (دان)، مسلة كيلاموا ملك سمأل، ومسلة النصر لعيزانا بأكسوم.",
      inscriptionalWitnessesEn = "Code of Hammurabi stele (diorite, Louvre), Mesha Stele of Moab (basalt, Louvre), Tel Dan Stele ('House of David'), Kilamuwa stele of Sam'al, and Ezana trilingual stele.",
      ancientSampleGlyphs = "مسلات صخرية ذات رؤوس مقوسة منقوشة بالكامل",
      ancientScriptType = "النقوش التذكارية الملكية (Monumental Lapidary)",
      philologicalImportanceAr = "تُعد أهم وثائق التاريخ الإبيغرافي القديم، حيث صيغت بأعلى درجات الفصاحة والبلاغة اللغوية الملكية في عصرها.",
      philologicalImportanceEn = "Represents the pinnacle of formal chancery prose, providing the standard for classical grammar and royal ideology across ancient civilizations.",
      relatedTermIds = listOf("colophon", "damnatio_memoriae", "squeeze_estampage"),
      citation = "Pritchard, J. B. (Ancient Near Eastern Texts - ANET); Hallo, W. W."
    ),

    EpigraphicGlossaryTerm(
      id = "palimpsest",
      termAr = "الطِّرْس المُمحى المُستعاد (باليمبسست)",
      termEn = "Palimpsest",
      transliteration = "palímpsēstos (παλίμψηστος)",
      categoryAr = "الآثار ومواد التدوين",
      categoryEn = "Archaeology & Paleography",
      shortDefinitionAr = "رقّ أو مخطوط جلدي تم كشط أو محو نصه القديم لإعادة الكتابة فوقه بسبب ندرة وغلاء أدوات التدوين.",
      shortDefinitionEn = "A manuscript parchment or writing surface that has been scraped or washed clean to be reused for a second text.",
      detailedDefinitionAr = "ظاهرة أثرية ناتجة عن التكلفة الباهظة للجلود والرقوق في العصور القديمة. كان النساخ يقومون بحك النص القديم بالحجر الخفاف وغسله لكتابة نص جديد فوقه. باستخدام تقنيات التصوير الطيفي الحديثة (Multispectral Imaging)، يتمكن الباحثون اليوم من قراءة الطبقة التحتية الممسوحة وكشف نصوص ومفردات مفقودة منذ آلاف السنين.",
      detailedDefinitionEn = "A parchment or papyrus scraped clean and inscribed a second time. Modern multispectral imaging and infrared illumination enable epigraphers to resurrect erased undertexts (scriptio inferior) of lost literary and legal works.",
      inscriptionalWitnessesAr = "طرس صنعاء الشهير للمصاحف المبكرة (المخطوط العتيق المكتوب فوق طبقة أقدم)، ومخطوطات دير سانت كاترين بالسريانية والآرامية المسيحية، وبعض الرقوق القبطية والجعزية.",
      inscriptionalWitnessesEn = "The Sana'a palimpsest of early Quranic leaves; Saint Catherine's Monastery Christian Palestinian Aramaic and Caucasian Albanian palimpsests.",
      ancientSampleGlyphs = "طبقتان من الحبر: طبقة عليا سوداء وطبقة سفلى باهتة تكشفها الأشعة",
      ancientScriptType = "المخطوطات والرقوق القديمة (Codicology & MSI)",
      philologicalImportanceAr = "يفتح نافذة لا تقدر بثمن على نصوص تاريخية كان يُعتقد أنها أُتلفت وانقرضت للأبد، ويكشف تطور الخط عبر الزمن على نفس الرقعة.",
      philologicalImportanceEn = "Provides unprecedented access to lost classical and biblical recensions, demonstrating textual transmission and orthographic evolution over centuries.",
      relatedTermIds = listOf("squeeze_estampage", "ductus", "ostrakon"),
      citation = "Toth, M. B. (Multispectral Imaging of Palimpsests); Sadeghi & Goudarzi."
    ),

    // 5. Comparative Semitics & Historical Linguistics
    EpigraphicGlossaryTerm(
      id = "isogloss",
      termAr = "خَطُّ التَّمَايُزِ اللَّهَجِيِّ الجُغْرافِيِّ (الإيزوغلوص)",
      termEn = "Isogloss",
      transliteration = "isogloss (ἴσος + γλῶσσα)",
      categoryAr = "اللسانيات المقارنة",
      categoryEn = "Comparative Semitics",
      shortDefinitionAr = "خط جغرافي حدودي على الخريطة يرسم النطاق المكاني الذي تسود فيه سمة صوتية أو صرفية معينة بين اللغات واللهجات.",
      shortDefinitionEn = "A geographic boundary line demarcating the distribution of a specific linguistic feature, sound law, or lexical variant.",
      detailedDefinitionAr = "أداة جوهرية في علم الجغرافيا اللغوية والساميات المقارنة. يُرسم الإيزوغلوص على أطلس الخرائط الأثرية لبيان حدود انتشار ظاهرة معينة؛ مثل خط حدود التحول الكنعاني (*ā > ō)، أو خط التمييز بين أداة التعريف بالهاء (الكنعانية والعربية الشمالية) وأداة التعريف بالألف اللام (العربية الفصحى)، أو خط اللاحقة الميمية مقابل النونية.",
      detailedDefinitionEn = "A mapping construct that demarcates where linguistic innovations took root. Crucial in Semitic studies for plotting dialect continua across Iron Age Syria-Palestine and distinguishing core languages from transitional zones.",
      inscriptionalWitnessesAr = "خريطة لهجات بلاد الشام في الألف الأول ق.م (التمايز بين فينيقية الساحل، وعبرية المرتفعات، ومؤابية شرق الأردن، وآرامية دمشق).",
      inscriptionalWitnessesEn = "Garr's seminal dialect geography of Syria-Palestine, tracing the boundaries between coastal Phoenician, highland Hebrew, Transjordanian Ammonite/Moabite, and inland Old Aramaic.",
      ancientSampleGlyphs = "خطوط حدودية: (هـ / 𐤄ـ) مقابل (الـ) | (ـم) مقابل (ـن)",
      ancientScriptType = "الأطلس اللغوي المقارن (Dialect Geography)",
      philologicalImportanceAr = "يُمكن علماء اللسانيات من تفكيك النظريات القديمة الصارمة وإثبات أن اللغات السامية كانت عبارة عن طيف متدرج ومستمر من اللهجات المتداخلة (Dialect Continuum).",
      philologicalImportanceEn = "Replaced rigid tree models with wave-theory dialect continua, demonstrating how linguistic innovations radiated across trade routes in the ancient Near East.",
      relatedTermIds = listOf("canaanite_shift", "mimation_nunation", "cognate"),
      citation = "Garr, W. R. (Dialect Geography of Syria-Palestine, 1000-586 B.C.E.); Hetzron, R. (The Semitic Languages)."
    ),

    EpigraphicGlossaryTerm(
      id = "cognate",
      termAr = "المُفْرَدَة السَّامِيَّة المُشْتَرَكَة المُؤَصَّلَة (كوغنيت)",
      termEn = "Cognate",
      transliteration = "Cognate / المشترك اللغوي السامي",
      categoryAr = "اللسانيات المقارنة",
      categoryEn = "Comparative Semitics",
